import type { NextRequest } from "next/server";
import { getProduct } from "@/lib/products";

export async function GET(_request: NextRequest, ctx: RouteContext<"/api/products/[slug]">) {
  const { slug } = await ctx.params;
  const product = await getProduct(slug);
  if (!product) {
    return Response.json({ error: "No such product" }, { status: 404 });
  }
  return Response.json({
    slug: product.slug,
    name: product.name,
    priceCents: product.priceCents,
    inStock: product.inStock,
  });
}

steps.body:
A Route Handler can answer anything, which makes it tempting to use one for everything. Most of the time a Server Component or a Server Action is the better tool, and choosing right saves you a round trip, a public endpoint to secure, and code to keep in step. The question that decides it is who sends the request.

```diagram route-handlers-and-proxy-who-calls
Your own pages need no endpoint. Everyone else gets a Route Handler.
```

## Not for your own pages

Your own pages don't need an endpoint to read data. A Server Component fetches it straight from its source, the API or the database. Calling your own Route Handler from a Server Component sends a second HTTP request to your own server for nothing. A page prerendered at build time can't call it at all, since no server is running during the build. Your own forms don't need one either, since Server Actions handle writes. That's the first two rows of the diagram. The other three are callers outside your React code, and each needs a real URL.

## Webhooks

A webhook, which the caching lesson used to clear a tag, is a request another service sends to your URL when something happens on its side: a payment went through, a product's stock changed. You give the service a URL, and it POSTs an event there. A stock system could tell the shop when stock changes, so the cached product can be refreshed. The course's Trailhead API doesn't send webhooks, so you'll play that service's part yourself and send the event with a terminal command.

Anyone can POST to that URL, so the service signs each event. The usual way is an **HMAC**, a code computed from the request body and a secret that only you and the service know. The service sends the code in a header, and your handler computes it again from the body it got. When the two match, the event is genuine and unchanged. Three details matter:

- Compute it over the raw body from `request.text()`, before parsing, since parsing JSON and writing it out again can change the bytes.
- Compare the two codes with `timingSafeEqual` from `node:crypto`. It takes the same time however much of the code matches, so nobody can guess a code one character at a time by timing your answers.
- Keep the secret in an environment variable, like `STOCK_WEBHOOK_SECRET` in `.env.local`, never in your code.

After the check, the handler calls `revalidateTag(`product-${slug}`, "max")`. `updateTag` only works in Server Actions, and a change no visitor is waiting on suits the stale-while-revalidate way anyway. Answer fast with a 2xx: services send an event again when your answer is slow or fails, so a webhook handler does its slow work after the response, which part 5 shows.

## Other apps and other sites

A phone app, a partner's site, or a script of yours may want your products as JSON. A Route Handler is your public API for them, and it needs the care any API does: check the input, identify callers, often with a token in an `Authorization` header since other apps don't share your cookies, and send CORS headers when a page on another origin calls it from a browser. Part 4 shows CORS.

## Feeds, files, and streams

Some answers aren't pages or JSON: a CSV of orders, a generated PDF, or an RSS feed, the XML format that feed readers follow. `new Response(body, { headers: { "Content-Type": "text/xml" } })` sends any of them.

A handler can also stream. **Server-sent events**, from the web course, keep one response open and send a small event whenever there's news, which a page reads with `EventSource`. Return a `ReadableStream`, and each chunk you write goes out at once. This is `app/api/stock/[slug]/events/route.ts`:

```ts
import { getStock } from "@/lib/products";

export async function GET(request: Request, ctx: RouteContext<"/api/stock/[slug]/events">) {
  const { slug } = await ctx.params;
  const encoder = new TextEncoder();

  const stream = new ReadableStream({
    async start(controller) {
      for (let i = 0; i < 3 && !request.signal.aborted; i++) {
        const stock = await getStock(slug);
        controller.enqueue(encoder.encode(`event: stock\ndata: ${JSON.stringify({ stock })}\n\n`));
        await new Promise((resolve) => setTimeout(resolve, 1000));
      }
      controller.close();
    },
  });

  return new Response(stream, {
    headers: { "Content-Type": "text/event-stream", "Cache-Control": "no-cache" },
  });
}
```

Each event is a few lines of text ending in a blank line: `event:` names it, and `data:` carries it. `TextEncoder` turns the text into bytes, which is what a stream holds. `getStock`, the uncached stock reader from the caching lesson, asks the API afresh each time round the loop. `request.signal.aborted` turns true when the visitor leaves, so the loop stops instead of polling for nobody. A real stream would run until then. This one sends three events, a second apart, then closes.

examples.code:
import { createHmac, timingSafeEqual } from "node:crypto";
import { revalidateTag } from "next/cache";
import { after } from "next/server";

function signatureIsValid(body: string, signature: string | null) {
  if (!signature) return false;
  const expected = createHmac("sha256", process.env.STOCK_WEBHOOK_SECRET!).update(body).digest("hex");
  const a = Buffer.from(expected);
  const b = Buffer.from(signature);
  return a.length === b.length && timingSafeEqual(a, b);
}

export async function POST(request: Request) {
  const body = await request.text();
  if (!signatureIsValid(body, request.headers.get("x-trailhead-signature"))) {
    return Response.json({ error: "Bad signature" }, { status: 401 });
  }

  const event = JSON.parse(body) as { type: string; slug: string };
  if (event.type === "stock.changed") {
    revalidateTag(`product-${event.slug}`, "max");
  }

  after(() => {
    console.log(`webhook ${event.type} for ${event.slug} handled`);
  });
  return new Response(null, { status: 204 });
}

