import { NextResponse, type NextRequest } from "next/server";

export function proxy(request: NextRequest) {
  const { pathname, search } = request.nextUrl;

  if (pathname.startsWith("/account") && !request.cookies.has("th_session")) {
    const login = new URL("/login", request.url);
    login.searchParams.set("next", pathname + search);
    return NextResponse.redirect(login);
  }

  const requestId = crypto.randomUUID();
  const headers = new Headers(request.headers);
  headers.set("x-request-id", requestId);

  const response = NextResponse.next({ request: { headers } });
  response.headers.set("x-request-id", requestId);
  return response;
}

export const config = {
  matcher: ["/((?!_next/static|_next/image|favicon.ico|images/).*)"],
};

steps.body:
Headers carry a lot of an app's rules. A cookie holds the session, CORS headers say which other sites may read your API, and `Cache-Control` says how long a browser or a CDN may keep a copy. Each has a right place in Next.js, and putting one in the wrong place either fails with an error or quietly does nothing.

## Cookies: read anywhere, set where something changes

`cookies()` from `next/headers` reads the request's cookies on the server, in Server Components, Server Actions, and Route Handlers. Setting or deleting one is allowed in only two of those, the ones that answer a request that changes something: Server Actions and Route Handlers. The shop's login action, a Server Action on the login page that the lesson on secrets and auth comes back to, sets the session cookie like this:

```ts
(await cookies()).set("th_session", token, {
  httpOnly: true,
  secure: true,
  sameSite: "lax",
  path: "/",
  maxAge: 60 * 60 * 24 * 7,
});
```

These are the cookie flags from the web course: `httpOnly` hides the cookie from JavaScript, `secure` sends it only over HTTPS, `sameSite: "lax"` keeps it off most requests from other sites, and `maxAge` is its lifetime in seconds, a week here. A Server Component can't set a cookie. Rendering must never change anything, since a page can render at build time, render again for a prefetch, or be cached and shown to many visitors. Proxy can set one too, on the response it returns, with `response.cookies.set(...)`.

## CORS for your API

The browser's same-origin policy, from the web course, lets a page read responses only from its own origin unless the other origin allows it. A Route Handler that a partner's site calls from the browser has to send that permission: an `Access-Control-Allow-Origin` header naming the partner's origin. For a request that isn't simple, like one with a custom header, a JSON body, or a method other than GET, HEAD, and POST, the browser first sends a **preflight**, an `OPTIONS` request asking what's allowed, so the handler exports its own `OPTIONS` too. The second example does both.

Keep a list of allowed origins rather than sending `*`, which means anyone, and send `Vary: Origin` so a cache never hands one origin's answer to another. The browser refuses `*` outright for requests that carry cookies. For many handlers, the same headers can be set in proxy or in `next.config.ts` instead of in each file.

## Fixed headers in next.config.ts

A header that never changes belongs in the config. `headers()` in `next.config.ts` returns a list of path patterns, each with the headers to add, and Next.js applies them before proxy, to pages, handlers, and `public/` files alike:

```ts
import type { NextConfig } from "next";

const nextConfig: NextConfig = {
  cacheComponents: true,
  async headers() {
    return [
      {
        source: "/images/:path*",
        headers: [{ key: "Cache-Control", value: "public, max-age=86400" }],
      },
    ];
  },
};

export default nextConfig;
```

That gives the shop's product photos in `public/images` a day in the browser's cache. The security lesson puts its security headers in the same place.

## The caching headers Next.js sets for you

Before you add a caching header, check what's already there. Next.js picks `Cache-Control` by what kind of response it is:

| Response | Cache-Control |
|---|---|
| a hashed file in `/_next/static` | `public, max-age=31536000, immutable`, which you can't change |
| a file in `public/` | `public, max-age=0`, unless the config adds one |
| a fully static page with no cache lifetime | `s-maxage=31536000` |
| a page prerendered with `cacheLife("hours")` | `s-maxage=3600, stale-while-revalidate=82800` |
| a page with parts rendered per request | `private, no-cache, no-store, max-age=0, must-revalidate` |
| a Route Handler's response | none, unless you set one |

The first row is the web course's rule for hashed files: the name changes whenever the content does, so a copy can be kept for a year. Files in `public/` keep their names across builds, so they're checked again each time unless you say otherwise. The `s-maxage` on a prerendered page is for CDNs, the shared caches between you and your visitors, and the `private` on a page with per-request parts keeps it out of them. A handler that sets `Cache-Control: public` lets a CDN answer later requests for that URL without running the handler at all, so its checks and limits don't run either. Only cache a handler's answer when it's safe to give to anyone who has the URL.

examples.code:
import type { NextRequest } from "next/server";
import { listProducts } from "@/lib/products";

const allowedOrigins = ["https://partner.example"];

function corsHeaders(origin: string | null): Record<string, string> {
  if (!origin || !allowedOrigins.includes(origin)) return {};
  return {
    "Access-Control-Allow-Origin": origin,
    "Access-Control-Allow-Methods": "GET, OPTIONS",
    "Access-Control-Allow-Headers": "Content-Type",
    "Access-Control-Max-Age": "600",
    Vary: "Origin",
  };
}

export async function OPTIONS(request: NextRequest) {
  return new Response(null, { status: 204, headers: corsHeaders(request.headers.get("origin")) });
}

export async function GET(request: NextRequest) {
  const category = request.nextUrl.searchParams.get("category");
  const products = await listProducts();
  const items = category ? products.filter((p) => p.category === category) : products;
  return Response.json({ items }, { headers: corsHeaders(request.headers.get("origin")) });
}

import type { Instrumentation } from "next";

export function register() {
  console.log(`instrumentation: server starting (${process.env.NEXT_RUNTIME})`);
}

export const onRequestError: Instrumentation.onRequestError = async (error, request, context) => {
  const message = error instanceof Error ? error.message : String(error);
  console.log(
    JSON.stringify({
      level: "error",
      message,
      method: request.method,
      path: request.path,
      routePath: context.routePath,
      routeType: context.routeType,
    }),
  );
};
